begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id,email) select ('51000000-0000-0000-0000-00000000000'||n)::uuid,'route-command-'||n||'@example.test' from generate_series(1,3) n;
insert into auth.sessions(id,user_id) select ('52000000-0000-0000-0000-00000000000'||n)::uuid,('51000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3) n;
update app.profiles set beta_access=true where id::text like '51000000-%';
insert into app.carriers(id,slug,display_name,visibility) select ('53000000-0000-0000-0000-00000000000'||n)::uuid,'route-command-'||n,'Command Carrier '||n,'published' from generate_series(1,2) n;
insert into app.carrier_memberships(carrier_id,user_id,role) select ('53000000-0000-0000-0000-00000000000'||n)::uuid,('51000000-0000-0000-0000-00000000000'||n)::uuid,'owner' from generate_series(1,2) n;
insert into app.carrier_private_details(carrier_id,legal_name,business_kind,registration_country)
select ('53000000-0000-0000-0000-00000000000'||n)::uuid,'Legal Carrier '||n,case when n=1 then 'individual' else 'company' end,'LT' from generate_series(1,2) n;
create function pg_temp.payload() returns jsonb language sql as $$
select jsonb_build_object('stops',array['hamburg-de','berlin-de','kaunas-lt'],'date_from',current_date+30,'date_to',current_date+35,
'capacity_total',3,'supported_categories',array['car','motorcycle'],'supports_non_running',true,'route_flexible',true,'accepting_new_requests',true);
$$;
create function pg_temp.route_id() returns uuid language sql as $$select current_setting('test.route_id')::uuid$$;
set local role anon;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'42501',null,'anon cannot create/publish');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"51000000-0000-0000-0000-000000000003","session_id":"52000000-0000-0000-0000-000000000003"}',true);
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'42501',null,'customer cannot create/publish');
select set_config('request.jwt.claims','{"sub":"51000000-0000-0000-0000-000000000001","session_id":"52000000-0000-0000-0000-000000000001"}',true);
select extensions.lives_ok($$select set_config('test.route_id',api.save_route(pg_temp.payload(),false,null,null,'54000000-0000-0000-0000-000000000001')::text,true)$$,'admitted owner creates draft without any verification or capabilities');
select extensions.is((select carrier_id from api.my_routes where id=pg_temp.route_id()),'53000000-0000-0000-0000-000000000001'::uuid,'carrier resolved from authenticated owner');
select extensions.is((select count(*)::int from api.public_routes),0,'draft not public');
select extensions.is((select capacity_reserved from api.my_routes),0,'creation reserves nothing');
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid(),'route-command-2')$$,'42501',null,'Carrier slug selection never grants another Carrier authority');
select extensions.is(api.save_route(pg_temp.payload(),false,null,null,'54000000-0000-0000-0000-000000000001'),pg_temp.route_id(),'creation retry returns canonical ID');
select extensions.is((select count(*)::int from api.my_routes),1,'creation retry does not duplicate');
select extensions.lives_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),1)$$,'owner publishes saved draft without generic verified badge');
select extensions.is((select capacity_reserved from api.my_routes),0,'publication reserves nothing');
select extensions.is((select count(*)::int from api.public_routes),1,'published route visible');
select extensions.is((select route_flexible from api.my_routes),true,'flexibility persisted');
select extensions.is((select supports_non_running from api.my_routes),true,'non-running persisted');
select extensions.is((select count(*)::int from api.public_route_stops),3,'existing waypoints persisted');
select extensions.lives_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),1)$$,'same publication retry succeeds without new revision');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"carrier_id":"53000000-0000-0000-0000-000000000002"}',true,null,null,gen_random_uuid())$$,'22023',null,'cannot publish for browser-supplied carrier');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"capacity_reserved":2}',true,null,null,gen_random_uuid())$$,'22023',null,'reserved capacity input rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"verified_carrier":true}',true,null,null,gen_random_uuid())$$,'22023',null,'verification input rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"supported_categories":["truck"]}',true,null,null,gen_random_uuid())$$,'23514',null,'unsupported category rejected by command');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"stops":["hamburg-de","PRIVATE exact address"]}',true,null,null,gen_random_uuid())$$,'22023',null,'arbitrary address rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"stops":["hamburg-de","hamburg-de"]}',true,null,null,gen_random_uuid())$$,'22023',null,'identical endpoints rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"stops":[]}',true,null,null,gen_random_uuid())$$,'22023',null,'missing endpoints rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"route_flexible":"true"}',true,null,null,gen_random_uuid())$$,'22023',null,'string boolean rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"route_flexible":null}',true,null,null,gen_random_uuid())$$,'22023',null,'null boolean rejected');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"capacity_total":1.5}',true,null,null,gen_random_uuid())$$,'22023',null,'fractional capacity rejected before cast');
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||jsonb_build_object('date_to',current_date-1),true,null,null,gen_random_uuid())$$,'22023',null,'invalid dates rejected');
select extensions.is((select count(*)::int from api.my_routes),1,'failed creates rollback atomically');
select extensions.lives_ok($$select api.save_route(pg_temp.payload()||'{"capacity_total":4,"stops":["hamburg-de","warsaw-pl","kaunas-lt"]}',true,pg_temp.route_id(),1)$$,'owner edits capacity and ordered stops atomically');
select extensions.is((select route_version from api.my_routes),2,'material edit advances version');
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),1)$$,'40001',null,'stale edit rejected');
reset role;
select extensions.is((select count(*)::int from app.route_revisions where route_id=pg_temp.route_id()),2,'immutable revision history');
select extensions.is((select count(*)::int from app.audit_log where entity_id=pg_temp.route_id() and action='carrierRoute.published'),1,'publication boundary recorded once');
update app.carrier_routes set capacity_reserved=3 where id=pg_temp.route_id();
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload()||'{"capacity_total":2}',true,pg_temp.route_id(),2)$$,'23514',null,'command cannot reduce total below reserved');
select extensions.is((select capacity_total from api.my_routes),4,'failed edit preserves previous capacity');
select set_config('request.jwt.claims','{"sub":"51000000-0000-0000-0000-000000000002","session_id":"52000000-0000-0000-0000-000000000002"}',true);
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),2)$$,'42501',null,'another carrier cannot edit/publish route');
select extensions.throws_ok($$select api.close_route(pg_temp.route_id(),2)$$,'42501',null,'another carrier cannot close');
select extensions.lives_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'company uses same beta rule without verification');
select set_config('request.jwt.claims','{"sub":"51000000-0000-0000-0000-000000000001","session_id":"52000000-0000-0000-0000-000000000001"}',true);
reset role;
update app.profiles set beta_access=false where id='51000000-0000-0000-0000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),2)$$,'42501',null,'withdrawn owner beta admission blocks edit');
select extensions.throws_ok($$select api.close_route(pg_temp.route_id(),2)$$,'42501',null,'withdrawn beta admission blocks close');
reset role;
update app.profiles set beta_access=true where id='51000000-0000-0000-0000-000000000001';
update app.carriers set visibility='draft' where id='53000000-0000-0000-0000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'42501',null,'carrier lacking explicit public admission cannot create');
reset role;
update app.carriers set visibility='published',suspended_at=now() where id='53000000-0000-0000-0000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),2)$$,'42501',null,'suspended carrier cannot edit');
reset role;
update app.carriers set suspended_at=null where id='53000000-0000-0000-0000-000000000001';
update app.profiles set account_status='suspended' where id='51000000-0000-0000-0000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'42501',null,'suspended account cannot publish');
reset role;
update app.profiles set account_status='active' where id='51000000-0000-0000-0000-000000000001';
delete from app.carrier_private_details where carrier_id='53000000-0000-0000-0000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'42501',null,'missing legal profile blocks publication');
reset role;
insert into app.carrier_private_details(carrier_id,legal_name,business_kind,registration_country) values('53000000-0000-0000-0000-000000000001','Legal name','individual','LT');
set local role authenticated;
select extensions.lives_ok($$select api.close_route(pg_temp.route_id(),2)$$,'eligible owner closes own route');
select extensions.is((select count(*)::int from api.public_routes where id=pg_temp.route_id()),0,'closed route excluded from public');
select extensions.is((select capacity_reserved from api.my_routes where id=pg_temp.route_id()),3,'closure does not release capacity');
select extensions.lives_ok($$select api.close_route(pg_temp.route_id(),2)$$,'close retry safe');
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,pg_temp.route_id(),2)$$,'42501',null,'closed route cannot republish');
reset role;
insert into app.carriers(id,slug,display_name,visibility) values('53000000-0000-0000-0000-000000000003','route-command-second-owned','Second owned Carrier','published');
insert into app.carrier_memberships(carrier_id,user_id,role) values('53000000-0000-0000-0000-000000000003','51000000-0000-0000-0000-000000000001','owner');
insert into app.carrier_private_details(carrier_id,legal_name,business_kind,registration_country) values('53000000-0000-0000-0000-000000000003','Second legal profile','company','LT');
set local role authenticated;
select extensions.lives_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid(),'route-command-second-owned')$$,'single owner may own another Carrier without a new ownership restriction');
select extensions.is((select count(*)::int from api.my_routes where carrier_id='53000000-0000-0000-0000-000000000003'),1,'selected Carrier is resolved against live ownership');
reset role;
delete from auth.sessions where id='52000000-0000-0000-0000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select api.save_route(pg_temp.payload(),true,null,null,gen_random_uuid())$$,'42501',null,'revoked live session blocks valid JWT');
reset role;
-- Restore the Phase 3 synthetic reservation; Phase 4 requires Booking-backed counters.
update app.carrier_routes set capacity_reserved=0 where id=pg_temp.route_id();
set constraints all immediate;
select * from extensions.finish();
rollback;
